import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from ficha import *
# Guía 02 · SVA del adulto, ERC 2025. 11 diapositivas. Familia Guía (azul).
T="GUÍA 02 · SVA ERC 2025"; N=11; KW=dict(famc=B)
note=lambda t: f'<div style="font-size:34px;line-height:1.4;color:{G}">{t}</div>'
rows=lambda *x: '<div style="display:flex;flex-direction:column;gap:18px">'+"".join(x)+'</div>'
tag=lambda t,c=B: f'<div style="align-self:flex-start;background:{c};color:#FFF;padding:10px 22px;border-radius:8px;font-size:34px;font-weight:800;letter-spacing:4px">{t}</div>'
red=lambda t: f'<div style="border-top:4px solid {K};padding-top:20px;font-size:40px;font-weight:800;line-height:1.3;color:{R}">{t}</div>'
def tabla(H,D,cols,fs=36):
    th="".join(f'<div style="font-weight:800;font-size:{fs}px;color:{B}">{h}</div>' for h in H)
    tr="".join("".join(f'<div style="font-size:{fs}px;font-weight:700;border-top:3px solid {K};padding-top:12px;line-height:1.25">{c}</div>' for c in r) for r in D)
    return f'<div style="display:grid;grid-template-columns:{cols};gap:12px 18px">{th}{tr}</div>'
P=[
page(1,N,T,f'<div style="font-size:40px;font-weight:800;letter-spacing:6px;color:{Y}">GUÍA 02 · ERC 2025</div>'+big("SOPORTE VITAL AVANZADO",132,"#FFFFFF")+big(f'LA FV FINA <span style="color:{Y}">TAMBIÉN SE DESCARGA</span>',112,"#FFFFFF")+'<div style="font-size:38px;font-weight:600;line-height:1.3;max-width:860px">Guías 2025 del European Resuscitation Council para el adulto: el algoritmo completo y lo que cambia respecto a 2021.</div>',cover=True,**KW),
page(2,N,T,tag("PASO 1 · LO QUE MÁS PESA")+big("RCP DE CALIDAD",150,R,True)+rows(row("Profundidad","5–6 cm"),row("Frecuencia","100–120/min"),row("Sin vía aérea avanzada","30:2"),row("Con tubo o supraglótico","Compresiones continuas, 10 ventilaciones/min"),row("Pausa para descargar","&lt; 5 s: carga comprimiendo"))+note("Analiza el ritmo cada 2 minutos. Tras la descarga, vuelve a comprimir sin mirar el pulso."),**KW),
page(3,N,T,tag("PASO 2 · FV O TV SIN PULSO",R)+big("DESFIBRILABLE",144,R,True)+rows(row("Descarga","≥ 150 J bifásica; la máxima si no conoces el equipo"),row("Después","RCP 2 min y reanaliza"),row("Adrenalina","1 mg tras la 3.ª descarga; luego cada 3–5 min"),row("Amiodarona","300 mg tras la 3.ª; 150 mg tras la 5.ª"),row("Sin amiodarona","Lidocaína 100 mg (+ 50 mg tras la 5.ª)"))+note("Descarga cualquier FV, también la fina. Puedes subir la energía en las descargas siguientes."),**KW),
page(4,N,T,tag("PASO 2 · ASISTOLIA O AESP")+big("NO DESFIBRILABLE",122,R,True)+rows(row("Adrenalina","1 mg lo antes posible"),row("Repite","Cada 3–5 min"),row("Ciclos","RCP 2 min y reanaliza"))+red("Busca la causa desde el primer minuto: es lo que puede cambiar el pronóstico"),**KW),
page(5,N,T,tag("SI LA FV NO CEDE")+big("FV REFRACTARIA",140,R,True)+'<div style="font-size:44px;font-weight:800;line-height:1.25">Persiste tras 3 descargas seguidas</div>'+rows(line("Comprueba los parches: el apical, bajo la axila, en la línea medioaxilar",True),line("Cambia de vector: de anterolateral a anteroposterior"),line("La doble descarga secuencial no se recomienda de rutina")),**KW),
page(6,N,T,tag("PASO 3 · BUSCA LA CAUSA")+big("4H Y 4T",200,R,True)+tabla(["H","T"],[("Hipoxia","Trombosis coronaria o pulmonar"),("Hipovolemia","Neumotórax a tensión"),("Hipo/hiperpotasemia y metabólicas","Taponamiento cardiaco"),("Hipo/hipertermia","Tóxicos")],"1fr 1fr",36)+note("Ecografía sin parar las compresiones más de 10 s: graba el clip y míralo comprimiendo."),**KW),
page(7,N,T,tag("PASO 4 · VÍA AÉREA")+big("CAPNOGRAFÍA",160,R,True)+rows(row("Intubación","Solo con experiencia; pausa &lt; 5 s"),row("Confirmar el tubo","Curva de ETCO2 mantenida: obligatoria"),row("ETCO2 que sube","Puede ser recuperación; no pares solo por eso"),row("ETCO2 &lt; 10 mmHg","No lo uses solo para decidir parar"))+note("La vía aérea, escalonada: de la bolsa y mascarilla al supraglótico y al tubo, según tu experiencia."),**KW),
page(8,N,T,tag("PASO 5 · ACCESO Y FÁRMACOS")+big("IV PRIMERO",180,R,True)+rows(row("Acceso","IV; intraósea si fallan 2 intentos"),row("No de rutina","Calcio, bicarbonato, corticoides"),row("TEP como causa","Fibrinólisis y RCP 60–90 min después"),row("Consciente durante la RCP","Sedación y analgesia")),**KW),
page(9,N,T,tag("TRAS LA RECUPERACIÓN")+big("RCE: OBJETIVOS",140,R,True)+rows(row("Oxígeno","SatO2 94–98 %"),row("Presión","Evita la hipotensión: PAM &gt; 65 mmHg"),row("Temperatura","Evita la fiebre (≤ 37,5 °C si está en coma)"),row("ECG","Coronariografía inmediata si el ST está elevado")),**KW),
page(10,N,T,tag("2025 FRENTE A 2021",R)+big("¿QUÉ CAMBIA?",130,nowrap=True)+rows(line("La FV fina también se descarga",True),line("Capnografía obligatoria para confirmar el tubo"),line("Vía IV antes que intraósea"),line("Sin calcio, bicarbonato ni corticoides de rutina"),line("Cambio de vector en la FV refractaria"),line("Adiós al golpe precordial"))+note("Son cambios de énfasis: el algoritmo es el mismo."),**KW),
page(11,N,T,ficha_body("SVA ADULTO","ERC 2025",[("RCP","5–6 cm, 100–120/min, 30:2. Con vía aérea avanzada, 10 ventilaciones/min"),("DESFIBRILABLE","Descarga ≥ 150 J y RCP 2 min. Adrenalina 1 mg y amiodarona 300 mg tras la 3.ª; amiodarona 150 mg tras la 5.ª",True),("NO DESFIBR.","Adrenalina 1 mg lo antes posible y cada 3–5 min",True),("REFRACTARIA","Revisa los parches y cambia a anteroposterior"),("4H · 4T","Hipoxia, hipovolemia, potasio, temperatura · trombosis, neumotórax, taponamiento, tóxicos"),("VÍA AÉREA","Pausa &lt; 5 s para intubar. Capnografía obligatoria"),("ACCESO","IV primero; intraósea si fallan 2 intentos"),("TRAS RCE","SatO2 94–98 %, PAM &gt; 65, sin fiebre. Coronariografía si ST elevado")],"Soar J, et al. ERC Guidelines 2025 Adult Advanced Life Support. Resuscitation 2025;215 Suppl 1:110769; Greif R, et al. ERC 2025 Executive Summary",size=124,fs=25),fam="GUÍA",ficha="02",**KW),
]
render(P,sys.argv[1] if len(sys.argv)>1 else "out","guia-sva-erc2025")
